group "default" {
  targets = ["api", "web"]
}

target "api" {
  context    = "./api"
  dockerfile = "Dockerfile"
  tags       = ["ghcr.io/acme/api:dev"]
  platforms  = ["linux/amd64", "linux/arm64"]
}

target "web" {
  context = "./web"
  tags    = ["ghcr.io/acme/web:dev"]
  args    = { NODE_VERSION = "22" }
}

