variable "TAG" { default = "dev" }
variable "REGISTRY" { default = "ghcr.io/acme" }

target "_common" {
  platforms = ["linux/amd64", "linux/arm64"]
  args = { BUILDKIT_INLINE_CACHE = "1" }
}

target "api" {
  inherits = ["_common"]
  context  = "./api"
  tags     = ["${REGISTRY}/api:${TAG}"]
}

target "web" {
  inherits = ["_common"]
  context  = "./web"
  tags     = ["${REGISTRY}/web:${TAG}"]
}

target "api" {
  name = "api-${tgt}"
  matrix = {
    tgt = ["debug", "release"]
  }
  target = tgt
  tags   = ["ghcr.io/acme/api:${tgt}"]
}
